CREATE TABLE "b" (
  "id" int PRIMARY KEY
);

CREATE TABLE "a" (
  "id" int PRIMARY KEY,
  "b_id" int,
  "self" int
);

ALTER TABLE "a" ADD FOREIGN KEY ("b_id") REFERENCES "b" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "a" ADD FOREIGN KEY ("self") REFERENCES "a" ("id") DEFERRABLE INITIALLY IMMEDIATE;

-- Defer constraint checking for INSERT
BEGIN;
SET CONSTRAINTS ALL DEFERRED;

INSERT INTO "b" ("id")
VALUES
  (1);
INSERT INTO "a" ("id", "b_id", "self")
VALUES
  (1, 1, 1),
  (2, 9, NULL);

SET CONSTRAINTS ALL IMMEDIATE;
COMMIT;